namespace sv_373cfbd63b3d4a56a38666130bf2c1d7.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// In interactive server mode, "scoped" = per-circuit, so each user
/// gets independent state that survives enhanced navigations.
/// </summary>
public sealed class ThemeService
{
    private Theme _theme = Theme.System;
    private string _accentColor = "#0d6efd";

    public Theme Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyStateChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyStateChanged();
        }
    }

    /// <summary>
    /// All interactive components subscribe to this event.
    /// When any component mutates state, every subscriber re-renders.
    /// </summary>
    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();
}

@* Interactive island in the static layout header — shares circuit-scoped ThemeService *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeSvc

<span class="badge rounded-pill"
      style="background-color: @ThemeSvc.AccentColor; color: white;">
    @ThemeSvc.Theme
</span>

@code {
    protected override void OnInitialized()
        => ThemeSvc.OnChange += StateHasChanged;

    public void Dispose()
        => ThemeSvc.OnChange -= StateHasChanged;
}

@* Interactive island in the sidebar — quick theme cycle button *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeSvc

<div class="nav-item px-3 py-2">
    <button class="btn btn-sm w-100"
            style="background-color: @ThemeSvc.AccentColor; color: white;"
            @onclick="CycleTheme">
        🎨 @ThemeSvc.Theme Mode
    </button>
</div>

@code {
    private void CycleTheme()
    {
        ThemeSvc.Theme = ThemeSvc.Theme switch
        {
            Theme.Light  => Theme.Dark,
            Theme.Dark   => Theme.System,
            _            => Theme.Light
        };
    }

    protected override void OnInitialized()
        => ThemeSvc.OnChange += StateHasChanged;

    public void Dispose()
        => ThemeSvc.OnChange -= StateHasChanged;
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeSvc

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-3" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var t in Enum.GetValues<Theme>())
            {
                var isActive = ThemeSvc.Theme == t;
                <button class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => ThemeSvc.Theme = t">
                    @t
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <div class="d-flex align-items-center gap-3">
            <input type="color"
                   class="form-control form-control-color"
                   value="@ThemeSvc.AccentColor"
                   @onchange="OnColorChanged" />
            <span class="badge rounded-pill"
                  style="background-color: @ThemeSvc.AccentColor; color: white;">
                @ThemeSvc.AccentColor
            </span>
        </div>
    </div>
</div>

@code {
    private void OnColorChanged(ChangeEventArgs e)
        => ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd";

    protected override void OnInitialized()
        => ThemeSvc.OnChange += StateHasChanged;

    public void Dispose()
        => ThemeSvc.OnChange -= StateHasChanged;
}

