+    public string AccentColor
+    {
+        get => _accentColor;
+        set
+        {
+            if (_accentColor == value) return;
+            _accentColor = value;
+            NotifyStateChanged();
+        }
+    }
+
+    /// <summary>
+    /// All interactive components subscribe to this event.
+    /// When any component mutates state, every subscriber re-renders.
+    /// </summary>
+    public event Action? OnChange;
+
+    private void NotifyStateChanged() => OnChange?.Invoke();
+}
